const RIVAL_BY={}; RIVALS.forEach((R,i)=>{ R.i=i; R.num=1+hash(R.k)%45; RIVAL_BY[R.k]=R; });
function dayNum(){ return Math.floor(Date.now()/86400000); }
// ratings drift a little day to day so the board feels alive (the cast stays in its rank)
function rivalRR(R){ return Math.max(0, Math.round(R.rr + Math.sin(dayNum()*0.7 + hash(R.k)%17)*40)); }
// their look: same gear every time; better ranks flex rarer stuff
function rivalGear(R){
  const ti=rankOf(R.rr).ti, cap = ti<=2?1 : ti<=5?2 : ti<=8?3 : 4, g={};
  for(const k in KINDS){ const pool=KINDS[k].list.filter(i=>RORDER.indexOf(i.r)<=cap); g[k]=pool[hash(R.k+k)%pool.length].id; }
  return g;
}
// how they play: difficulty from their rating, bent by their style
function rivalDiff(R){
  const rr=rivalRR(R), d=diffForRR(rr), m=STYLES[R.style].mod;
  d.plant=lerp(0.3, 0.92, clamp(rr/2000,0,1));     // better players set their feet before they shoot
  d.moves=lerp(0.35, 1, clamp(rr/1800,0,1));        // ...and have a deeper bag of moves
  for(const key in m) d[key]=(d[key]??1)*m[key];
  d.plant=Math.min(0.97,d.plant);
  d.name=R.n; return d;
}

// @@DIFF-BEGIN (also copied by the game server)
// bots get tougher as you climb: blend Rookie -> Pro -> Legend by rating
function diffForRR(rr){
  // Bronze-Silver: Scrub -> Rookie, Gold-Emerald: Rookie -> Pro, Master+: Pro -> Legend
  const L=[[0,BOTDIFF.scrub],[810,BOTDIFF.rookie],[1860,BOTDIFF.pro],[3390,BOTDIFF.legend]], d={};
  let j=0; while(j<L.length-2 && rr>=L[j+1][0]) j++;
  const [r0,x]=L[j], [r1,y]=L[j+1], k=clamp((rr-r0)/(r1-r0),0,1);
  for(const key of ['shotSd','burst','dodge','slide','jump','steal','speed','cushion']) d[key]=lerp(x[key],y[key],k);
  d.name='Ranked'; return d;
}

  return { newMatch, stepMatch, makeSnap, findP, looseBall, BOTDIFF, RIVALS, RIVAL_BY, rivalRR, diffForRR, BOT_NAMES, MAX_PER_TEAM, hash, cleanName, Q };
